local ContextActionService = game:GetService("ContextActionService")
local RunService = game:GetService("RunService")
local Input = require(script.Input)
local Keys = require(script.Keys)
local module = {}
module._activatedStack = {}
module._inputs = {}

function module:Init(folder)
    local all = {}
    for i, v in pairs(folder:GetChildren()) do
        if v:IsA("ModuleScript") then
            local inputsFolder = v:FindFirstChild("Input")
            if inputsFolder and inputsFolder:IsA("Folder") and inputsFolder:FindFirstChild("GameController") then
                for j, k in pairs(inputsFolder.GameController:GetChildren()) do
                    if k:IsA("ModuleScript") then
                        local suc, res = pcall(function()
                            local input = Input.new(k, self)
                            table.insert(all, k)
                        end)
                        if not suc then
                            warn(k)
                            warn(res)
                            warn(debug.traceback())
                        end
                    end
                end
            end
        end
    end
    return all
end

function module:Push(input)
    for i, v in pairs(module._activatedStack) do
        if v == input then
            return
        end
    end
    table.insert(module._activatedStack, input)
    self:_reloadInputs()
end
function module:Remove(input)
    for i, v in pairs(module._activatedStack) do
        if v == input then
            table.remove(module._activatedStack, i)
            for _, v in pairs(input._actions) do
                v:_setIconShow(false)
            end
            break
        end
    end
    self:_reloadInputs()
end

function module:_reloadInputs()
    local inputs = {}
    local isGlobal = false
    for i = #self._activatedStack, 1, -1 do
        local input = self._activatedStack[i]
        table.insert(inputs, input)

        if input.Sinked then
            isGlobal = true
            break
        end
    end
    for i, v in pairs(self._activatedStack) do
        for j, action in pairs(v._actions) do
            action:_setIconShow(false)
        end
    end
    self:_checkActions(inputs, isGlobal)
end

function module:_checkActions(inputs, isGlobal)
    local keyActions = {}
    for i, input in pairs(inputs) do
        for j, action in pairs(input._actions) do
            local key = action.Key
            if keyActions[key] then
                continue
            end
            keyActions[key] = action
            action:_setIconShow(true)
        end
    end
    self:_reloadBinding(keyActions, isGlobal)
end

local DEAD_ZONE = 0.5
function module:_reloadBinding(keyActions, isGlobal)
    local keys = {}
    if isGlobal then
        keys = Keys:GetAllKeyCodes()
    else
        local temp = {}
        for i, v in pairs(keyActions) do
            local key = string.split(i, "+")
            for j, k in pairs(key) do
                if not temp[k] then
                    table.insert(keys, Enum.KeyCode[k])
                    temp[k] = true
                end
            end
        end
        keys = Keys:GetKeyCodes(temp)
    end

    ContextActionService:UnbindAction("InputAdapter")

    
    local pressed = {}

    local function runCombineAction(keycode)
        if #pressed < 2 then
            return
        end
        local combineKey = table.concat(pressed, "+")
        local action = keyActions[combineKey]
        if action then
            action:Execute()
            return true
        end
    end

    local function runSingleAction(keycode)
        local action = keyActions[keycode]
        if action then
            action:Execute()
            return true
        end
    end
    
    local thumbstickDirection = ""
    local function thumbstickMove(direction)
        local action = keyActions["Thumbstick1"]
        if not action then
            return
        end
        if thumbstickDirection == direction then
            return
        end
        thumbstickDirection = direction
        local t = 0.5
        local first = true
        RunService:UnbindFromRenderStep("ThumbstickMove")
        RunService:BindToRenderStep("ThumbstickMove", Enum.RenderPriority.Input.Value, function(dt)
            t += dt
            if t > 0.5 then
                if first then
                    first = false
                    t = 0
                else
                    t = 0.4
                end
                action.KeyEvent:Fire(thumbstickDirection)
            end
        end)
    end

    ContextActionService:BindActionAtPriority("InputAdapter", function(actionName, state, inputObject: InputObject)
        local runCombine = false
        if inputObject.UserInputType == Enum.UserInputType.Gamepad1 then
            local key = inputObject.KeyCode.Name
            if inputObject.KeyCode == Enum.KeyCode.Thumbstick1 then
                local position = inputObject.Position
                local moved = false
                if math.abs(position.X) > DEAD_ZONE then
                    if position.X > 0 then
                        -- right
                        thumbstickMove("right")
                        moved = true
                    else
                        -- left
                        thumbstickMove("left")
                        moved = true
                    end
                end
                if math.abs(position.Y) > DEAD_ZONE then
                    if position.Y > 0 then
                        -- up
                        thumbstickMove("up")
                        moved = true
                    else
                        -- down
                        thumbstickMove("down")
                        moved = true
                    end
                end
                if not moved then
                    thumbstickMove("center")
                end
            end

            if state == Enum.UserInputState.Begin then
                if not table.find(pressed, key) then
                    table.insert(pressed, key)
                end
                runCombine = runCombineAction(key)
                if not runCombine then
                    runSingleAction(key)
                end
                for i, v in pairs(keyActions) do
                    if string.find(i, key) == 1 and string.find(i, "+") then
                        v:_setIconShow(true, #pressed == 1)
                    end
                end
            elseif state == Enum.UserInputState.End then
                for i, v in pairs(pressed) do
                    if v == key then
                        table.remove(pressed, i)
                    end
                end
                for i, v in pairs(keyActions) do
                    if string.find(i, key) == 1 and string.find(i, "+") then
                        v:_setIconShow(true)
                    end
                end
            elseif state == Enum.UserInputState.Cancel then
                for i, v in pairs(pressed) do
                    if v == key then
                        table.remove(pressed, i)
                    end
                end
                for i, v in pairs(keyActions) do
                    if string.find(i, key) == 1 and string.find(i, "+") then
                        v:_setIconShow(true)
                    end
                end
            end
            
            if not (isGlobal or runCombine) then
                return Enum.ContextActionResult.Pass
            end
        end
    end, false, Enum.ContextActionPriority.High.Value, table.unpack(keys))
end

return module